<template>
  <div class="pm-dashboard-layout"><AppSidebar :isOpen="sidebarOpen" @close="sidebarOpen=false" /><main class="pm-dashboard-main"><header class="pm-dashboard-topbar"><button class="pm-icon-btn pm-menu-btn" type="button" @click="sidebarOpen=!sidebarOpen">☰</button><div class="pm-topbar-search"><input v-model="filters.search" class="form-control" placeholder="Search..." @keyup.enter="load"></div></header><section class="pm-dashboard-content"><div class="container pm-ops-page workflow-page">
    <div class="workflow-title-row"><h1>{{ config.title }} <small>- {{ showForm ? (form.id ? 'Edit' : config.newTitle) : config.listTitle }}</small></h1><button v-if="showForm" class="btn btn-outline-secondary" type="button" @click="showForm=false">List</button></div>
    <section v-if="!showForm" class="pm-card workflow-filter"><h2>⌕&nbsp; Filters</h2><div class="filter-grid"><label>Date From<input v-model="filters.date_from" class="form-control" type="date"></label><label>Date To<input v-model="filters.date_to" class="form-control" type="date"></label><label>{{ config.personLabel }}<input v-model="filters.staff" class="form-control" :placeholder="`All ${config.personPlural}`"></label><label>Department<input v-model="filters.department" class="form-control" placeholder="All Departments"></label><label>{{ config.typeLabel }}<select v-model="filters.type" class="form-control"><option value="">All {{ config.typeLabel }}s</option><option v-for="option in config.types" :key="option" :value="option">{{ label(option) }}</option></select></label><label>Status<select v-model="filters.status" class="form-control"><option value="">All Statuses</option><option v-for="option in config.statuses" :key="option" :value="option">{{ label(option) }}</option></select></label><label>Priority<select v-model="filters.priority" class="form-control"><option value="">All Priorities</option><option value="low">Low</option><option value="normal">Normal</option><option value="high">High</option><option value="urgent">Urgent</option></select></label><div class="filter-actions"><button class="btn btn-primary" type="button" @click="load">⌕ Search</button><button class="btn btn-outline-secondary" type="button" @click="clear">↻ Clear</button><button class="btn btn-outline-secondary" type="button" @click="exportCsv">⇩ Export</button></div></div></section>
    <section v-if="!showForm && type==='task'" class="task-stats"><div v-for="card in taskStats" :key="card.label" class="task-stat" :class="card.tone"><span>{{ card.label }}</span><strong>{{ card.value }}</strong></div></section>
    <section v-if="!showForm" class="pm-card workflow-list"><div class="section-heading"><h2>▣&nbsp; {{ config.title }} List ({{ records.length }})</h2><button class="btn btn-primary" type="button" @click="create">＋ New {{ config.singular }}</button></div><div class="table-responsive"><table class="table workflow-table"><thead><tr><th>No.</th><th>{{ config.numberLabel }}</th><th>{{ config.titleColumn }}</th><th>{{ config.personLabel }}</th><th>Department</th><th>{{ config.dateColumn }}</th><th>Customer / Job</th><th>Priority</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="(record,index) in records" :key="record.id"><td>{{ index+1 }}</td><td>{{ record.record_no }}</td><td><strong>{{ record.title }}</strong><small v-if="record.notes">{{ record.notes }}</small></td><td>{{ person(record)||'—' }}</td><td>{{ record.department||'—' }}</td><td>{{ formatRange(record) }}</td><td>{{ record.customer_job_site||record.location_site||'—' }}</td><td><span class="priority" :class="`priority-${record.priority||'normal'}`">{{ label(record.priority||'normal') }}</span></td><td><span class="workflow-status" :class="`is-${record.status}`">{{ label(record.status) }}</span></td><td><button class="view-button" type="button" @click="edit(record)">◉ View</button></td></tr><tr v-if="!loading&&!records.length"><td colspan="10" class="empty">No {{ config.title.toLowerCase() }} records found.</td></tr></tbody></table></div><div class="workflow-pagination">Showing 1 to {{ records.length }} of {{ records.length }} entries</div></section>
    <form v-else class="workflow-form" @submit.prevent="save"><section class="pm-card"><h2>1.&nbsp; {{ config.infoTitle }}</h2><div class="form-grid"><label>{{ config.numberLabel }}<input class="form-control" :value="form.record_no||'Generated when saved'" disabled></label><label>Date *<input v-model="form.record_date" type="date" class="form-control" required></label><label>Priority<select v-model="form.priority" class="form-control"><option value="low">Low</option><option value="normal">Normal</option><option value="high">High</option><option value="urgent">Urgent</option></select></label><label>Status<select v-model="form.status" class="form-control"><option v-for="option in config.statuses" :key="option" :value="option">{{ label(option) }}</option></select></label></div></section><section class="pm-card"><h2>2.&nbsp; {{ config.peopleTitle }}</h2><div class="form-grid"><label>{{ config.personLabel }} *<input v-model="form[config.personField]" class="form-control" required></label><label>Department<input v-model="form.department" class="form-control"></label><label>Position / Title<input v-model="details.position_title" class="form-control"></label><label>Phone<input v-model="details.phone" class="form-control"></label></div></section><section class="pm-card"><h2>3.&nbsp; {{ config.detailTitle }}</h2><div class="form-grid"><label class="span-2">{{ config.titleColumn }} *<input v-model="form.title" class="form-control" required></label><label>{{ config.typeLabel }}<select v-model="form.request_type" class="form-control"><option value="">Select {{ config.typeLabel }}</option><option v-for="option in config.types" :key="option" :value="option">{{ label(option) }}</option></select></label><label>Customer / Job Site<input v-model="form.customer_job_site" class="form-control"></label><label>Location / Site<input v-model="form.location_site" class="form-control"></label><label>Start Date & Time<input v-model="form.start_at" type="datetime-local" class="form-control"></label><label>{{ config.endLabel }}<input v-model="form.end_at" type="datetime-local" class="form-control"></label><label>Work Handover To<input v-model="details.handover_to" class="form-control"></label><label class="span-2">Details / Description *<textarea v-model="form.notes" class="form-control" rows="4" required></textarea></label></div></section><section class="pm-card"><h2>4.&nbsp; Approval Information</h2><div class="form-grid"><label>Immediate Supervisor<input v-model="details.supervisor" class="form-control"></label><label>Approval Status<select v-model="details.approval_status" class="form-control"><option value="pending">Pending</option><option value="approved">Approved</option><option value="rejected">Rejected</option></select></label><label class="span-2">Comments<textarea v-model="details.comments" class="form-control" rows="2"></textarea></label></div></section><div class="form-actions"><button class="btn btn-outline-secondary" type="button" @click="showForm=false">Cancel</button><button class="btn btn-outline-secondary" type="button" @click="reset">Reset</button><button class="btn btn-primary" :disabled="saving">{{ saving?'Saving…':'Save' }}</button><button class="btn btn-primary" type="button" :disabled="saving" @click="saveAndNew">Save & New</button><button v-if="form.id" class="btn btn-outline-danger" type="button" @click="remove">Delete</button></div></form>
  </div></section></main></div>
</template>

<script setup>
import { computed,onMounted,reactive,ref } from 'vue'
import AppSidebar from '../components/AppSidebar.vue'
import client from '../api/client'
const props=defineProps({type:{type:String,required:true}})
const definitions={request:{number:'4',title:'Staff Request',singular:'Request',newTitle:'New Request',listTitle:'Request List',endpoint:'staff-requests',numberLabel:'Request No.',personLabel:'Staff Name',personPlural:'Staff',personField:'staff_name',titleColumn:'Reason for Request',typeLabel:'Type',dateColumn:'Requested For',endLabel:'Return to Work',infoTitle:'Request Info',peopleTitle:'Request By',detailTitle:'Request Details',types:['vacation','sick_leave','personal_leave','remote_work','shift_change','schedule_change','education_training'],statuses:['new','pending','approved','rejected']},task:{number:'5',title:'Task Assignment',singular:'Task',newTitle:'New Task',listTitle:'Records',endpoint:'task-assignments',numberLabel:'Task No.',personLabel:'Assigned To',personPlural:'Staff',personField:'assigned_to',titleColumn:'Task Details / Explanation',typeLabel:'Task Type',dateColumn:'Due Date',endLabel:'Due Date & Time',infoTitle:'Task Info',peopleTitle:'Assigned By / To',detailTitle:'Task Details',types:['maintenance','inspection','repair','cleaning','emergency'],statuses:['open','assigned','in_progress','completed','overdue','cancelled']},schedule:{number:'7',title:'Work Schedule',singular:'Schedule',newTitle:'New Schedule',listTitle:'Staff Schedule List',endpoint:'work-schedules',numberLabel:'Schedule No.',personLabel:'Employee / Staff',personPlural:'Employees',personField:'staff_name',titleColumn:'Shift / Schedule Title',typeLabel:'Shift',dateColumn:'Schedule Period',endLabel:'End Date & Time',infoTitle:'Schedule Info',peopleTitle:'Employee Info',detailTitle:'Schedule Details',types:['day_shift','evening_shift','night_shift','stat_holiday'],statuses:['scheduled','confirmed','completed','cancelled']}}
const config=computed(()=>definitions[props.type]),sidebarOpen=ref(false),records=ref([]),loading=ref(false),saving=ref(false),showForm=ref(false),today=new Date().toISOString().slice(0,10),filters=reactive({date_from:'',date_to:'',staff:'',department:'',type:'',status:'',priority:'',search:''})
const blank=()=>({id:null,record_no:'',record_date:today,title:'',request_type:'',staff_name:'',assigned_to:'',location_site:'',customer_job_site:'',department:'',start_at:'',end_at:'',status:config.value.statuses[0],priority:'normal',notes:'',details_json:{}}),form=reactive(blank()),details=reactive({})
const taskStats=computed(()=>[['Total Tasks',records.value.length,''],['Completed',records.value.filter(r=>r.status==='completed').length,'success'],['In Progress',records.value.filter(r=>r.status==='in_progress').length,'warning'],['Open',records.value.filter(r=>['open','assigned'].includes(r.status)).length,'info'],['Overdue',records.value.filter(r=>r.status==='overdue').length,'danger']].map(([label,value,tone])=>({label,value,tone})))
const load=async()=>{loading.value=true;try{const {data}=await client.get(`/workforce/${config.value.endpoint}`,{params:filters});records.value=data?.data||[]}finally{loading.value=false}},clear=()=>{Object.assign(filters,{date_from:'',date_to:'',staff:'',department:'',type:'',status:'',priority:'',search:''});load()},create=()=>{Object.assign(form,blank());Object.assign(details,{});showForm.value=true},edit=async record=>{const {data}=await client.get(`/workforce/${config.value.endpoint}/${record.id}`),item=data.data;Object.assign(form,item,{start_at:inputDate(item.start_at),end_at:inputDate(item.end_at)});Object.assign(details,item.details_json||{});showForm.value=true},save=async()=>{saving.value=true;try{form.details_json={...details};const url=`/workforce/${config.value.endpoint}`;form.id?await client.put(`${url}/${form.id}`,form):await client.post(url,form);await load();showForm.value=false}finally{saving.value=false}},saveAndNew=async()=>{await save();create()},reset=()=>{const id=form.id;Object.assign(form,blank(),{id});Object.assign(details,{})},remove=async()=>{if(!confirm(`Delete this ${config.value.singular.toLowerCase()}?`))return;await client.delete(`/workforce/${config.value.endpoint}/${form.id}`);await load();showForm.value=false},person=record=>record[config.value.personField],label=value=>String(value||'').replaceAll('_',' ').replace(/\b\w/g,char=>char.toUpperCase()),inputDate=value=>value?new Date(value).toISOString().slice(0,16):'',formatDate=value=>value?new Date(value).toLocaleDateString():'—',formatRange=record=>record.end_at?`${formatDate(record.start_at||record.record_date)} – ${formatDate(record.end_at)}`:formatDate(record.start_at||record.record_date)
const exportCsv=()=>{const rows=[[config.value.numberLabel,config.value.titleColumn,config.value.personLabel,'Department','Status'],...records.value.map(r=>[r.record_no,r.title,person(r),r.department,r.status])],blob=new Blob([rows.map(row=>row.map(cell=>`"${String(cell||'').replaceAll('"','""')}"`).join(',')).join('\n')],{type:'text/csv'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`${config.value.endpoint}.csv`;link.click();URL.revokeObjectURL(link.href)};onMounted(load)
</script>

<style scoped>
