tton{border:1px solid #bfd0e6;background:white;color:#062a80;border-radius:4px;padding:.3rem .65rem;font-size:.78rem;font-weight:700}.empty{text-align:center;padding:2rem!important;color:#667085}.task-stats{display:grid;grid-template-columns:repeat(5,1fr);gap:1rem;margin-bottom:.85rem}.task-stat{display:flex;align-items:center;justify-content:space-between;border:1px solid #dbe2ee;border-radius:.35rem;background:#fff;padding:1.15rem 1.35rem}.task-stat span{font-weight:700;font-size:.86rem}.task-stat strong{font-size:1.65rem;color:#061e6b}.task-stat.success strong{color:#15803d}.task-stat.warning strong{color:#c78300}.task-stat.danger strong{color:#d92d20}.form-grid .span-2{grid-column:span 2}.form-actions{display:flex;justify-content:flex-end;gap:.75rem;padding:.35rem 0 1rem}@media(max-width:1000px){.filter-grid,.form-grid{grid-template-columns:repeat(2,1fr)}.task-stats{grid-template-columns:repeat(3,1fr)}}@media(max-width:600px){.workflow-page h1{font-size:1.55rem}.filter-grid,.form-grid,.task-stats{grid-template-columns:1fr}.form-grid .span-2{grid-column:auto}.filter-actions,.form-actions{flex-wrap:wrap}.section-heading{align-items:flex-start;gap:.75rem;flex-direction:column}}
.workflow-pagination{font-size:.8rem;padding-top:.8rem;background:transparent;color:#111827}
</style>
